      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': "Dead Man's a brass astrolabe", 'author': 'Signature original', 'genre': 'High Seas Adventures', 'chapters': [{'n': 1, 'title': 'The Chart', 'text': "a brass astrolabe came to Captain Maria Santos in a bottle, in a tavern, in the Devil's Triangle — as these things do. The parchment inside showed an island that wasn't on any map, and an X that was. the cabin boy Pip whistled. 'That's a voyage,' they said.\n\nThat night Captain Maria Santos stood at the wheel with a brass astrolabe's copy memorized and the original safe. Stars overhead, the Spanish governor astern, the Devil's Triangle behind. the sea tests all — the sea was about to test it.\n\nthe Spanish governor's sail was spotted on the third day — a black speck that didn't go away. 'They want a brass astrolabe,' the cabin boy Pip said. Captain Maria Santos nodded. 'Then they'll have to take it.' The crew cleared for action, grinning. They'd signed for this."}, {'n': 2, 'title': 'The Chase', 'text': "They took the Spanish governor's survivors aboard in irons — pirates have rules about the sea, even for enemies. 'The island eats ships,' Captain Maria Santos told the prisoners. 'Let's see if it eats villains too.'\n\nThe fight was ship to ship, rail to rail, cutlass to cutlass. the cabin boy Pip led the boarders with a roar. Captain Maria Santos dueled the Spanish governor's captain on the quarterdeck while the reef burned around them. When it was done, the Spanish governor's ship was sinking and theirs was afloat — barely.\n\nThey watered at a lagoon where the natives traded fruit for stories. Captain Maria Santos told the story of a brass astrolabe, leaving out the location. The chief laughed. 'The island you seek,' they said, 'eats ships.' Cheerful news."}, {'n': 3, 'title': "Dead Man's Cay", 'text': "The gold was there too — don't worry, there was gold — but Captain Maria Santos understood: a brass astrolabe was bigger than one chest. It was a lifetime of plunder, mapped. Enough to buy a fleet. Or a pardon. Or a future.\n\nThe island rose from the mist like a fist. a brass astrolabe led them past the reef — the reef that had the bones of a dozen ships in its teeth — to a beach of black sand. 'Eats ships,' the cabin boy Pip muttered. 'Charming.'\n\nInland: jungle, then ruins, then the cave. a brass astrolabe's X marked a chamber sealed a century. Inside: not gold — at first. A tomb. A logbook. The real a brass astrolabe: the captain's confession, naming every cache along the Devil's Triangle."}, {'n': 4, 'title': 'The Reckoning', 'text': "They sailed for the Devil's Triangle with the gold and a brass astrolabe and the logbook's secrets. The crew's shares would make them rich. Captain Maria Santos's share would make them legend. the cabin boy Pip was already spending theirs on a tavern.\n\nthe cabin boy Pip fought like three people. The crew fought like the sea itself. Captain Maria Santos faced the Spanish governor with cutlasses and old scores, and the duel was the kind they sing about: give, take, blood in the sand, neither yielding.\n\nOff the headland, Captain Maria Santos opened the logbook one last time. So many caches. So many voyages. the sea tests all — the sea had tested it, and it held."}, {'n': 5, 'title': 'Port and Pardon', 'text': "the cabin boy Pip's tavern opened to packed crowds: 'The a brass astrolabe.' The sign showed Captain Maria Santos with a cutlass and a grin. Captain Maria Santos pretended to mind. Nobody believed it.\n\nCaptain Maria Santos took the logbook to the governor — not the Spanish governor's governor, the new one — and traded certain pages for a pardon, signed and sealed. The crew cheered. Respectability, it turns out, is its own adventure.\n\nSome of the crew shipped out again, chasing the logbook's caches. Captain Maria Santos stayed — for a season. The sea calls, and Captain Maria Santos always answers. But home, Captain Maria Santos was learning, is also an answer."}, {'n': 6, 'title': 'The Tide Returns', 'text': "The new crew was young and wide-eyed. Captain Maria Santos read them the articles, including the added one. They cheered, the way crews do. Pirates are sentimentalists. It's why they survive.\n\nthe Devil's Triangle shrank astern again, beloved and boring in the best way. Ahead: a brass astrolabe, the sea, the test. Captain Maria Santos stood at the wheel and felt the old lift. This is the life.\n\nthe sea tests all. Full sail. The horizon, as always, was just the beginning."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

